import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const i=JSON.parse('{"title":"哀时命","description":"","frontmatter":{"title":"哀时命","date":"2026-11-24T00:00:00.000Z","seq":38,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"庄忌","source_book":"楚辞","prev":{"text":"谬谏","link":"/blogs/楚辞/谬谏.html"},"next":{"text":"匡机","link":"/blogs/楚辞/匡机.html"}},"headers":[],"relativePath":"blogs/楚辞/哀时命.md","filePath":"blogs/楚辞/哀时命.md"}'),o={name:"blogs/楚辞/哀时命.md"};function l(n,a,c,m,z,r){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="哀时命" tabindex="-1">哀时命 <a class="header-anchor" href="#哀时命" aria-label="Permalink to &quot;哀时命&quot;">​</a></h1><p class="poem-meta">先秦 · 庄忌　·　哀时命</p><div class="poem"><p class="poem-stanza">哀时命之不及古人兮，夫何予生之不遘时！</p><p class="poem-stanza">往者不可扳援兮，徠者不可与期。</p><p class="poem-stanza">志憾恨而不逞兮，杼中情而属诗。</p><p class="poem-stanza">夜炯炯而不寐兮，怀隐忧而历兹。</p><p class="poem-stanza">心郁郁而无告兮，众孰可与深谋！</p><p class="poem-stanza">欿愁悴而委惰兮，老冉冉而逮之。</p><p class="poem-stanza">居处愁以隐约兮，志沉抑而不扬。</p><p class="poem-stanza">道壅塞而不通兮，江河广而无梁。</p><p class="poem-stanza">愿至昆仑之悬圃兮，采锺山之玉英。</p><p class="poem-stanza">揽瑶木之橝枝兮，望阆风之板桐。</p><p class="poem-stanza">弱水汩其为难兮，路中断而不通。</p><p class="poem-stanza">势不能凌波以径度兮，又无羽翼而高翔。</p><p class="poem-stanza">然隐悯而不达兮，独徙倚而彷徉。</p><p class="poem-stanza">怅惝罔以永思兮，心纡轸而增伤。</p><p class="poem-stanza">倚踌躇以淹留兮，日饥馑而绝粮。</p><p class="poem-stanza">廓抱景而独倚兮，超永思乎故乡。</p><p class="poem-stanza">廓落寂而无友兮，谁可与玩此遗芳？</p><p class="poem-stanza">白日晼晼其將入兮，哀余寿之弗将。</p><p class="poem-stanza">车既弊而马罢兮，蹇邅徊而不能行。</p><p class="poem-stanza">身既不容于浊世兮，不知进退之宜当。</p><p class="poem-stanza">冠崔嵬而切云兮，剑淋离而从横。</p><p class="poem-stanza">衣摄叶以储与兮，左袪挂于榑桑</p><p class="poem-stanza">右衽拂于不周兮，六合不足以肆行。</p><p class="poem-stanza">上同凿枘于伏戏兮，下合矩矱于虞唐。</p><p class="poem-stanza">原尊节而式高兮，志犹卑夫禹汤。</p><p class="poem-stanza">虽知困其不改操兮，终不以邪枉害方。</p><p class="poem-stanza">世并举而好朋兮，壹斗斛而相量。</p><p class="poem-stanza">众比周以肩迫兮，贤者远而隐藏。</p><p class="poem-stanza">为凤皇作鹑笼兮，虽翕翅其不容。</p><p class="poem-stanza">灵皇其不寤知兮，焉陈词而效忠。</p><p class="poem-stanza">俗嫉妒而蔽贤兮，孰知余之从容？</p><p class="poem-stanza">愿舒志而抽冯兮，庸讵知其吉凶？</p><p class="poem-stanza">璋珪杂于甑窐兮，陇廉与孟娵同宫。</p><p class="poem-stanza">举世以为恆俗兮，固将愁苦而终穷。</p><p class="poem-stanza">幽独转而不寐兮，惟烦懑而盈匈。</p><p class="poem-stanza">魂眇眇而驰骋兮，心烦冤之忡忡。</p><p class="poem-stanza">志欿憾而不憺兮，路幽昧而甚难。</p><p class="poem-stanza">塊独守此曲隅兮，然欿切而永叹。</p><p class="poem-stanza">愁修夜而宛转兮，气涫沸其若波。</p><p class="poem-stanza">握剞劂而不用兮，操规矩而无所施。</p><p class="poem-stanza">骋骐骥于中庭兮，焉能极夫远道？</p><p class="poem-stanza">置援狖于棂槛兮，夫何以责其捷巧？</p><p class="poem-stanza">驷跛鳖而上山兮，吾固知其不能陞。</p><p class="poem-stanza">释管晏而任臧获兮，何权衡之能称？</p><p class="poem-stanza">箟簬杂于黀蒸兮，机蓬矢以射革。</p><p class="poem-stanza">负檐荷以丈尺兮，欲伸要而不可得。</p><p class="poem-stanza">外迫胁于机臂兮，上牵联于矰隿。</p><p class="poem-stanza">肩倾侧而不容兮，固陿腹而不得息。</p><p class="poem-stanza">务光自投于深渊兮，不获世之尘垢。</p><p class="poem-stanza">孰魁摧之可久兮，愿退身而穷处。</p><p class="poem-stanza">凿山楹而为室兮，下被衣于水渚。</p><p class="poem-stanza">雾露濛濛其晨降兮，云依斐而承宇。</p><p class="poem-stanza">虹霓纷其朝霞兮，夕淫淫而淋雨。</p><p class="poem-stanza">怊茫茫而无归兮，怅远望此旷野。</p><p class="poem-stanza">下垂钓于溪谷兮，上要求于仙者。</p><p class="poem-stanza">与赤松而结友兮，比王侨而为耦。</p><p class="poem-stanza">使枭杨先导兮，白虎为之前後。</p><p class="poem-stanza">浮云雾而入冥兮，骑白鹿而容与。</p><p class="poem-stanza">魂眐眐以寄独兮，汨徂往而不归。</p><p class="poem-stanza">处卓卓而日远兮，志浩荡而伤怀。</p><p class="poem-stanza">鸾凤翔于苍云兮，故矰缴而不能加。</p><p class="poem-stanza">蛟龙潜于旋渊兮，身不挂于罔罗。</p><p class="poem-stanza">知贪饵而近死兮，不如下游乎清波。</p><p class="poem-stanza">宁幽隐以远祸兮，孰侵辱之可为。</p><p class="poem-stanza">子胥死而成义兮，屈原沉于汨罗。</p><p class="poem-stanza">虽体解其不变兮，岂忠信之可化。</p><p class="poem-stanza">志怦怦而内直兮，履绳墨而不颇。</p><p class="poem-stanza">执权衡而无私兮，称轻重而不差。</p><p class="poem-stanza">摡尘垢之枉攘兮，除秽累而反真。</p><p class="poem-stanza">形体白而质素兮，中皎洁而淑清。</p><p class="poem-stanza">时猒饫而不用兮，且隐伏而远身。</p><p class="poem-stanza">聊窜端而匿迹兮，嗼寂默而无声。</p><p class="poem-stanza">独便悁而烦毒兮，焉发愤而筊抒。</p><p class="poem-stanza">时暧暧其将罢兮，遂闷叹而无名。</p><p class="poem-stanza">伯夷死于首阳兮，卒夭隐而不荣。</p><p class="poem-stanza">太公不遇文王兮，身至死而不得逞。</p><p class="poem-stanza">怀瑶象而佩琼兮，愿陈列而无正。</p><p class="poem-stanza">生天坠之若过兮，忽烂漫而无成。</p><p class="poem-stanza">邪气袭余之形体兮，疾憯怛而萌生。</p><p class="poem-stanza">原壹见阳春之白日兮，恐不终乎永年。</p></div>',3)])])}const d=s(o,[["render",l]]);export{i as __pageData,d as default};
